// POST /api/ops/ai/draft (ops.pb.js)
routerAdd("POST", "/api/ops/ai.draft", (e) => require(`${__hooks}/_a2app_impl.js`).op(e, "ai.draft", (ev) => ((e) => {
  const bridge = require(`${__hooks}/_craftbot_bridge.js`);
  const body = e.requestInfo().body || {};
  const topic = String(body.topic || '').trim();
  const tone = String(body.tone || 'friendly and concise');
  if (topic === '') {
    return e.json(400, { error: 'topic is required' });
  }
  const raw = bridge.callLLM(
    'Draft a short email newsletter about: ' +
      topic +
      '\nTone: ' +
      tone +
      '\n\nOutput format EXACTLY:\nSUBJECT: <one line>\n\n<newsletter body, 3-6 short paragraphs, plain text>',
    'You write crisp, engaging email newsletters.',
  );
  if (!raw) {
    return e.json(503, { error: 'AI is unavailable: no language model is connected (connect an AI agent to this app)' });
  }
  let subject = topic;
  let draft = raw.trim();
  const match = draft.match(/^SUBJECT:\s*(.+)\n+([\s\S]*)$/);
  if (match) {
    subject = match[1].trim();
    draft = match[2].trim();
  }
  return e.json(200, { subject: subject, body: draft });
})(ev)));

// GET /api/ops/integrations/status (ops.pb.js)
routerAdd("POST", "/api/ops/integrations.status", (e) => require(`${__hooks}/_a2app_impl.js`).op(e, "integrations.status", (ev) => ((e) => {
  // Any host's model: CraftBot's bridge or a running framework bridge (_craftbot_bridge.llmAvailable).
  const configured = require(`${__hooks}/_craftbot_bridge.js`).llmAvailable();
  return e.json(200, { llm: { connected: configured } });
})(ev)));
